/**
 * SVG Filter Effects Example - Demonstrates advanced SVG filter effects and transformations
 *
 * This example showcases various SVG filter effects including:
 * - Blur filters
 * - Drop shadows
 * - Color adjustments
 * - Composite operations
 * - Masking effects
 * - Gradient overlays
 * - Blend modes
 */
import { ColorMetrics } from '@kit.ArkUI'

@Entry
@Component
struct svgExample017 {
  // Blur filter states
  @State blurRadius: number = 0
  @State blurEnabled: boolean = false
  // Shadow filter states
  @State shadowRadius: number = 10
  @State shadowOffsetX: number = 5
  @State shadowOffsetY: number = 5
  @State shadowColor: Color = Color.Black
  @State shadowOpacity: number = 0.3
  // Color adjustment states
  @State brightnessValue: number = 100
  @State contrastValue: number = 100
  @State saturationValue: number = 100
  @State hueRotateValue: number = 0
  // Composite operation states
  @State compositeMode: number = 0
  @State compositeNames: string[] = [
    'SourceOver', 'SourceIn', 'SourceOut', 'SourceAtop',
    'DestinationOver', 'DestinationIn', 'DestinationOut', 'DestinationAtop',
    'XOR', 'Plus', 'Modulate', 'Screen', 'Overlay'
  ]
  // Masking states
  @State maskEnabled: boolean = false
  @State maskOpacity: number = 0.5
  // Gradient overlay states
  @State gradientEnabled: boolean = false
  @State gradientAngle: number = 0
  @State gradientColors: Color[] = [Color.Red, Color.Blue]
  @State gradientOpacity: number = 0.5
  // Blend mode states
  @State blendModeValue: number = 0
  @State blendModeNames: string[] = [
    'Normal', 'Multiply', 'Screen', 'Overlay',
    'Darken', 'Lighten', 'ColorDodge', 'ColorBurn',
    'HardLight', 'SoftLight', 'Difference', 'Exclusion'
  ]
  // Animation states
  @State animating: boolean = false
  @State animationProgress: number = 0
  @State pulseScale: number = 1.0
  @State rotateAngle: number = 0
  // UI states
  @State currentTab: number = 0
  @State showAdvanced: boolean = false
  @State selectedValue: string = 'blur'
  // Preset configurations
  @State presetIndex: number = 0
  @State presetNames: string[] = [
    'None', 'Soft Glow', 'Neon Effect', 'Vintage',
    'Dramatic', 'Ethereal', 'Cyberpunk', 'Pastel'
  ]

  build() {
    Tabs({ index: this.currentTab }) {
      // Tab 1: Blur Effects
      TabContent() {
        this.BlurEffectsTab()
      }
      .tabBar('Blur')

      // Tab 2: Shadow Effects
      TabContent() {
        this.ShadowEffectsTab()
      }
      .tabBar('Shadow')

      // Tab 3: Color Adjustments
      TabContent() {
        this.ColorAdjustmentsTab()
      }
      .tabBar('Color')

      // Tab 4: Composite Operations
      TabContent() {
        this.CompositeOperationsTab()
      }
      .tabBar('Composite')

      // Tab 5: Masking & Gradients
      TabContent() {
        this.MaskingGradientsTab()
      }
      .tabBar('Mask')

      // Tab 6: Blend Modes
      TabContent() {
        this.BlendModesTab()
      }
      .tabBar('Blend')

      // Tab 7: Presets
      TabContent() {
        this.PresetsTab()
      }
      .tabBar('Presets')

      // Tab 8: Animation
      TabContent() {
        this.AnimationTab()
      }
      .tabBar('Animate')
    }
    .width('100%')
    .height('100%')
  }

  @Builder
  BlurEffectsTab() {
    Scroll() {
      Column({ space: 15 }) {
        Text('SVG Blur Effects')
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .margin({ top: 20, bottom: 10 })

        Text('Apply Gaussian blur to SVG images')
          .fontSize(14)
          .fontColor(Color.Gray)

        Divider()

        // Blur control panel
        Column({ space: 10 }) {
          Text('Blur Radius: ' + this.blurRadius.toFixed(1))
            .fontSize(16)
            .fontWeight(FontWeight.Medium)

          Slider({
            min: 0,
            max: 20,
            value: this.blurRadius,
            step: 0.5
          })
            .width('100%')
            .onChange((value: number) => {
              this.blurRadius = value
            })

          Row({ space: 10 }) {
            Button('No Blur')
              .onClick(() => {
                this.blurRadius = 0
              })

            Button('Light Blur')
              .onClick(() => {
                this.blurRadius = 3
              })

            Button('Medium Blur')
              .onClick(() => {
                this.blurRadius = 8
              })

            Button('Heavy Blur')
              .onClick(() => {
                this.blurRadius = 15
              })
          }
          .width('100%')
        }
        .width('100%')
        .padding(15)
        .backgroundColor('#F5F5F5')
        .borderRadius(12)

        Divider()

        // Blur preview
        Column({ space: 10 }) {
          Text('Blur Preview')
            .fontSize(18)
            .fontWeight(FontWeight.Medium)

          Stack() {
            Image($r('app.media.testSvg'))
              .width(200)
              .height(200)
              .blur(this.blurRadius)
              .border({ width: 2, color: Color.Blue })
              .backgroundColor(Color.White)
          }
          .width(220)
          .height(220)
          .backgroundColor('#E0E0E0')
          .borderRadius(12)
        }
        .width('100%')
        .alignItems(HorizontalAlign.Center)

        Divider()

        // Blur comparison grid

        Text('Blur Comparison')
          .fontSize(18)
          .fontWeight(FontWeight.Medium)

        Grid() {
          GridItem() {
            Column({ space: 5 }) {
              Image($r('app.media.testSvg'))
                .width(100)
                .height(100)
                .border({ width: 1, color: Color.Gray })
              Text('No Blur').fontSize(12)
            }
          }

          GridItem() {
            Column({ space: 5 }) {
              Image($r('app.media.testSvg'))
                .width(100)
                .height(100)
                .blur(2)
                .border({ width: 1, color: Color.Gray })
              Text('2px').fontSize(12)
            }
          }

          GridItem() {
            Column({ space: 5 }) {
              Image($r('app.media.testSvg'))
                .width(100)
                .height(100)
                .blur(5)
                .border({ width: 1, color: Color.Gray })
              Text('5px').fontSize(12)
            }
          }

          GridItem() {
            Column({ space: 5 }) {
              Image($r('app.media.testSvg'))
                .width(100)
                .height(100)
                .blur(10)
                .border({ width: 1, color: Color.Gray })
              Text('10px').fontSize(12)
            }
          }

          GridItem() {
            Column({ space: 5 }) {
              Image($r('app.media.testSvg'))
                .width(100)
                .height(100)
                .blur(15)
                .border({ width: 1, color: Color.Gray })
              Text('15px').fontSize(12)
            }
          }

          GridItem() {
            Column({ space: 5 }) {
              Image($r('app.media.testSvg'))
                .width(100)
                .height(100)
                .blur(20)
                .border({ width: 1, color: Color.Gray })
              Text('20px').fontSize(12)
            }
          }
        }
        .columnsTemplate('1fr 1fr 1fr')
        .rowsTemplate('1fr 1fr')
        .columnsGap(10)
        .rowsGap(10)
        .width('100%')
        .height(280)
        .margin({ bottom: 20 })
      }
      .width('100%')
      .padding(15)
    }
    .width('100%')
    .height('100%')
  }

  @Builder
  ShadowEffectsTab() {
    Scroll() {
      Column({ space: 15 }) {
        Text('SVG Shadow Effects')
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .margin({ top: 20, bottom: 10 })

        Text('Add drop shadows to SVG images')
          .fontSize(14)
          .fontColor(Color.Gray)

        Divider()

        // Shadow control panel
        Column({ space: 10 }) {
          Text('Shadow Configuration')
            .fontSize(16)
            .fontWeight(FontWeight.Medium)

          // Shadow radius
          Text('Radius: ' + this.shadowRadius.toFixed(1))
            .fontSize(14)
          Slider({
            min: 0,
            max: 30,
            value: this.shadowRadius,
            step: 1
          })
            .width('100%')
            .onChange((value: number) => {
              this.shadowRadius = value
            })

          // Shadow offset X
          Text('Offset X: ' + this.shadowOffsetX.toFixed(1))
            .fontSize(14)
          Slider({
            min: -20,
            max: 20,
            value: this.shadowOffsetX,
            step: 1
          })
            .width('100%')
            .onChange((value: number) => {
              this.shadowOffsetX = value
            })

          // Shadow offset Y
          Text('Offset Y: ' + this.shadowOffsetY.toFixed(1))
            .fontSize(14)
          Slider({
            min: -20,
            max: 20,
            value: this.shadowOffsetY,
            step: 1
          })
            .width('100%')
            .onChange((value: number) => {
              this.shadowOffsetY = value
            })

          // Shadow opacity
          Text('Opacity: ' + (this.shadowOpacity * 100).toFixed(0) + '%')
            .fontSize(14)
          Slider({
            min: 0,
            max: 1,
            value: this.shadowOpacity,
            step: 0.05
          })
            .width('100%')
            .onChange((value: number) => {
              this.shadowOpacity = value
            })

          // Shadow color selection
          Text('Shadow Color')
            .fontSize(14)
          Row({ space: 8 }) {
            ForEach([Color.Black, Color.Red, Color.Blue, Color.Green, Color.Orange], (color: Color) => {
              Button()
                .width(40)
                .height(40)
                .backgroundColor(color)
                .border({
                  width: this.shadowColor === color ? 3 : 1,
                  color: this.shadowColor === color ? Color.Blue : Color.Gray
                })
                .onClick(() => {
                  this.shadowColor = color
                })
            })
          }
        }
        .width('100%')
        .padding(15)
        .backgroundColor('#F5F5F5')
        .borderRadius(12)

        Divider()

        // Shadow preview
        Column({ space: 10 }) {
          Text('Shadow Preview')
            .fontSize(18)
            .fontWeight(FontWeight.Medium)

          Stack() {
            Image($r('app.media.testSvg'))
              .width(200)
              .height(200)
              .shadow({
                radius: this.shadowRadius,
                color: this.shadowColor,
                offsetX: this.shadowOffsetX,
                offsetY: this.shadowOffsetY
              })
              .border({ width: 2, color: Color.Blue })
              .backgroundColor(Color.White)
          }
          .width(220)
          .height(220)
          .backgroundColor('#E0E0E0')
          .borderRadius(12)
        }
        .width('100%')
        .alignItems(HorizontalAlign.Center)

        Divider()

        // Preset shadows
        Text('Preset Shadows')
          .fontSize(18)
          .fontWeight(FontWeight.Medium)

        Grid() {
          GridItem() {
            Column({ space: 5 }) {
              Image($r('app.media.testSvg'))
                .width(80)
                .height(80)
                .shadow({
                  radius: 5,
                  color: Color.Black,
                  offsetX: 2,
                  offsetY: 2
                })
              Text('Soft').fontSize(12)
            }
          }

          GridItem() {
            Column({ space: 5 }) {
              Image($r('app.media.testSvg'))
                .width(80)
                .height(80)
                .shadow({
                  radius: 15,
                  color: Color.Black,
                  offsetX: 5,
                  offsetY: 5
                })
              Text('Medium').fontSize(12)
            }
          }

          GridItem() {
            Column({ space: 5 }) {
              Image($r('app.media.testSvg'))
                .width(80)
                .height(80)
                .shadow({
                  radius: 25,
                  color: Color.Black,
                  offsetX: 10,
                  offsetY: 10
                })
              Text('Large').fontSize(12)
            }
          }

          GridItem() {
            Column({ space: 5 }) {
              Image($r('app.media.testSvg'))
                .width(80)
                .height(80)
                .shadow({
                  radius: 10,
                  color: Color.Red,
                  offsetX: 0,
                  offsetY: 0
                })
              Text('Glow Red').fontSize(12)
            }
          }

          GridItem() {
            Column({ space: 5 }) {
              Image($r('app.media.testSvg'))
                .width(80)
                .height(80)
                .shadow({
                  radius: 10,
                  color: Color.Blue,
                  offsetX: 0,
                  offsetY: 0
                })
              Text('Glow Blue').fontSize(12)
            }
          }

          GridItem() {
            Column({ space: 5 }) {
              Image($r('app.media.testSvg'))
                .width(80)
                .height(80)
                .shadow({
                  radius: 8,
                  color: Color.Green,
                  offsetX: -3,
                  offsetY: 3
                })
              Text('Offset').fontSize(12)
            }
          }
        }
        .columnsTemplate('1fr 1fr 1fr')
        .rowsTemplate('1fr 1fr')
        .columnsGap(10)
        .rowsGap(10)
        .width('100%')
        .height(220)
        .margin({ bottom: 20 })
      }
      .width('100%')
      .padding(15)
    }
    .width('100%')
    .height('100%')
  }

  @Builder
  ColorAdjustmentsTab() {
    Scroll() {
      Column({ space: 15 }) {
        Text('SVG Color Adjustments')
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .margin({ top: 20, bottom: 10 })

        Text('Adjust brightness, contrast, saturation, and hue')
          .fontSize(14)
          .fontColor(Color.Gray)

        Divider()

        // Color adjustment controls
        Column({ space: 10 }) {
          Text('Brightness: ' + this.brightnessValue + '%')
            .fontSize(14)
          Slider({
            min: 0,
            max: 200,
            value: this.brightnessValue,
            step: 5
          })
            .width('100%')
            .onChange((value: number) => {
              this.brightnessValue = value
            })

          Text('Contrast: ' + this.contrastValue + '%')
            .fontSize(14)
          Slider({
            min: 0,
            max: 200,
            value: this.contrastValue,
            step: 5
          })
            .width('100%')
            .onChange((value: number) => {
              this.contrastValue = value
            })

          Text('Saturation: ' + this.saturationValue + '%')
            .fontSize(14)
          Slider({
            min: 0,
            max: 200,
            value: this.saturationValue,
            step: 5
          })
            .width('100%')
            .onChange((value: number) => {
              this.saturationValue = value
            })

          Text('Hue Rotate: ' + this.hueRotateValue + '°')
            .fontSize(14)
          Slider({
            min: 0,
            max: 360,
            value: this.hueRotateValue,
            step: 15
          })
            .width('100%')
            .onChange((value: number) => {
              this.hueRotateValue = value
            })

          Row({ space: 10 }) {
            Button('Reset')
              .onClick(() => {
                this.brightnessValue = 100
                this.contrastValue = 100
                this.saturationValue = 100
                this.hueRotateValue = 0
              })

            Button('High Contrast')
              .onClick(() => {
                this.brightnessValue = 110
                this.contrastValue = 150
                this.saturationValue = 120
                this.hueRotateValue = 0
              })

            Button('Vivid')
              .onClick(() => {
                this.brightnessValue = 105
                this.contrastValue = 110
                this.saturationValue = 150
                this.hueRotateValue = 0
              })
          }
        }
        .width('100%')
        .padding(15)
        .backgroundColor('#F5F5F5')
        .borderRadius(12)

        Divider()

        // Color adjustment preview
        Column({ space: 10 }) {
          Text('Color Adjustment Preview')
            .fontSize(18)
            .fontWeight(FontWeight.Medium)

          Stack() {
            Image($r('app.media.testSvg'))
              .width(200)
              .height(200)
              .brightness(this.brightnessValue / 100)
              .contrast(this.contrastValue / 100)
              .saturate(this.saturationValue / 100)
              .hueRotate(this.hueRotateValue)
              .border({ width: 2, color: Color.Blue })
              .backgroundColor(Color.White)
          }
          .width(220)
          .height(220)
          .backgroundColor('#E0E0E0')
          .borderRadius(12)
        }
        .width('100%')
        .alignItems(HorizontalAlign.Center)

        Divider()

        // Preset color adjustments
        Text('Preset Adjustments')
          .fontSize(18)
          .fontWeight(FontWeight.Medium)

        Grid() {
          GridItem() {
            Column({ space: 5 }) {
              Image($r('app.media.testSvg'))
                .width(80)
                .height(80)
                .brightness(1.2)
              Text('Bright').fontSize(12)
            }
          }

          GridItem() {
            Column({ space: 5 }) {
              Image($r('app.media.testSvg'))
                .width(80)
                .height(80)
                .contrast(1.5)
              Text('Contrast').fontSize(12)
            }
          }

          GridItem() {
            Column({ space: 5 }) {
              Image($r('app.media.testSvg'))
                .width(80)
                .height(80)
                .saturate(2.0)
              Text('Vivid').fontSize(12)
            }
          }

          GridItem() {
            Column({ space: 5 }) {
              Image($r('app.media.testSvg'))
                .width(80)
                .height(80)
                .grayscale(1)
              Text('Grayscale').fontSize(12)
            }
          }

          GridItem() {
            Column({ space: 5 }) {
              Image($r('app.media.testSvg'))
                .width(80)
                .height(80)
                .sepia(1)
              Text('Sepia').fontSize(12)
            }
          }

          GridItem() {
            Column({ space: 5 }) {
              Image($r('app.media.testSvg'))
                .width(80)
                .height(80)
                .invert(1)
              Text('Invert').fontSize(12)
            }
          }
        }
        .columnsTemplate('1fr 1fr 1fr')
        .rowsTemplate('1fr 1fr')
        .columnsGap(10)
        .rowsGap(10)
        .width('100%')
        .height(220)
        .margin({ bottom: 20 })
      }
      .width('100%')
      .padding(15)
    }
    .width('100%')
    .height('100%')
  }

  @Builder
  CompositeOperationsTab() {
    Scroll() {
      Column({ space: 15 }) {
        Text('SVG Composite Operations')
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .margin({ top: 20, bottom: 10 })

        Text('Blend SVG images with different composite modes')
          .fontSize(14)
          .fontColor(Color.Gray)

        Divider()

        // Composite mode selection
        Column({ space: 10 }) {
          Text('Current Mode: ' + this.compositeNames[this.compositeMode])
            .fontSize(16)
            .fontWeight(FontWeight.Medium)

          Row({ space: 8 }) {
            ForEach(this.compositeNames, (name: string, index: number) => {
              Button(name.substring(0, 4))
                .fontSize(10)
                .width(60)
                .height(35)
                .backgroundColor(this.compositeMode === index ? '#007AFF' : '#E0E0E0')
                .fontColor(this.compositeMode === index ? Color.White : Color.Black)
                .onClick(() => {
                  this.compositeMode = index
                })
            })
          }
        }
        .width('100%')
        .padding(15)
        .backgroundColor('#F5F5F5')
        .borderRadius(12)

        Divider()

        // Composite preview
        Column({ space: 10 }) {
          Text('Composite Preview')
            .fontSize(18)
            .fontWeight(FontWeight.Medium)

          Stack() {
            // Base layer
            Image($r('app.media.testSvg'))
              .width(200)
              .height(200)
              .fillColor(Color.Red)
              .border({ width: 2, color: Color.Blue })
              .backgroundColor(Color.White)

            // Composite layer
            Image($r('app.media.testSvg'))
              .width(150)
              .height(150)
              .fillColor(Color.Blue)
              .position({ x: 50, y: 50 })
          }
          .width(220)
          .height(220)
          .backgroundColor('#E0E0E0')
          .borderRadius(12)
        }
        .width('100%')
        .alignItems(HorizontalAlign.Center)

        Divider()

        // Composite modes grid
        Text('All Composite Modes')
          .fontSize(18)
          .fontWeight(FontWeight.Medium)

        Grid() {
          ForEach(this.compositeNames, (name: string, index: number) => {
            GridItem() {
              Column({ space: 5 }) {
                Stack() {
                  Image($r('app.media.testSvg'))
                    .width(80)
                    .height(80)
                    .fillColor(Color.Red)
                    .border({ width: 1, color: Color.Gray })

                  Image($r('app.media.testSvg'))
                    .width(50)
                    .height(50)
                    .fillColor(Color.Blue)
                    .position({ x: 20, y: 20 })
                }

                Text(name).fontSize(10)
              }
            }
          })
        }
        .columnsTemplate('1fr 1fr 1fr')
        .columnsGap(10)
        .rowsGap(10)
        .width('100%')
        .height(400)
        .margin({ bottom: 20 })
      }
      .width('100%')
      .padding(15)
    }
    .width('100%')
    .height('100%')
  }

  @Builder
  MaskingGradientsTab() {
    Scroll() {
      Column({ space: 15 }) {
        Text('SVG Masking & Gradients')
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .margin({ top: 20, bottom: 10 })

        Text('Apply masks and gradient overlays to SVG images')
          .fontSize(14)
          .fontColor(Color.Gray)

        Divider()

        // Masking controls
        Column({ space: 10 }) {
          Text('Masking')
            .fontSize(16)
            .fontWeight(FontWeight.Medium)

          Row({ space: 10 }) {
            Button('Enable Mask')
              .backgroundColor(this.maskEnabled ? '#007AFF' : '#E0E0E0')
              .onClick(() => {
                this.maskEnabled = !this.maskEnabled
              })

            Text('Opacity: ' + (this.maskOpacity * 100).toFixed(0) + '%')
              .fontSize(14)

            Slider({
              min: 0,
              max: 1,
              value: this.maskOpacity,
              step: 0.05
            })
              .width(100)
              .onChange((value: number) => {
                this.maskOpacity = value
              })
          }
        }
        .width('100%')
        .padding(15)
        .backgroundColor('#F5F5F5')
        .borderRadius(12)

        Divider()

        // Gradient controls
        Column({ space: 10 }) {
          Text('Gradient Overlay')
            .fontSize(16)
            .fontWeight(FontWeight.Medium)

          Row({ space: 10 }) {
            Button('Enable Gradient')
              .backgroundColor(this.gradientEnabled ? '#007AFF' : '#E0E0E0')
              .onClick(() => {
                this.gradientEnabled = !this.gradientEnabled
              })
          }

          Text('Angle: ' + this.gradientAngle + '°')
            .fontSize(14)
          Slider({
            min: 0,
            max: 360,
            value: this.gradientAngle,
            step: 15
          })
            .width('100%')
            .onChange((value: number) => {
              this.gradientAngle = value
            })

          Text('Opacity: ' + (this.gradientOpacity * 100).toFixed(0) + '%')
            .fontSize(14)
          Slider({
            min: 0,
            max: 1,
            value: this.gradientOpacity,
            step: 0.05
          })
            .width('100%')
            .onChange((value: number) => {
              this.gradientOpacity = value
            })

          Row({ space: 8 }) {
            ForEach([Color.Red, Color.Blue, Color.Green, Color.Orange, Color.Pink], (color: Color) => {
              Button()
                .width(35)
                .height(35)
                .backgroundColor(color)
                .border({ width: 1, color: Color.Gray })
                .onClick(() => {
                  this.gradientColors = [color, Color.White]
                })
            })
          }
        }
        .width('100%')
        .padding(15)
        .backgroundColor('#F5F5F5')
        .borderRadius(12)

        Divider()

        // Preview
        Column({ space: 10 }) {
